(()=>{const e=document.querySelector(".photo-viewer");if(!e||typeof e.showModal!="function")return;const t=e.querySelector(".photo-viewer-image");document.addEventListener("click",n=>{const s=n.target.closest("a[data-photo-zoom]");if(!s||n.button!==0||n.metaKey||n.ctrlKey||n.shiftKey||n.altKey)return;n.preventDefault(),t.alt=s.querySelector("img").alt,t.src=s.dataset.photoZoom,e.showModal(),document.documentElement.classList.add("photo-viewer-open")}),e.querySelector("button").addEventListener("click",()=>e.close()),e.addEventListener("click",t=>{t.target===e&&e.close()}),e.addEventListener("close",()=>{document.documentElement.classList.remove("photo-viewer-open"),t.removeAttribute("src"),t.alt=""})})()